        :root {
            --primary: #F5A623;
            --primary-dark: #d4891a;
            --secondary: #1a1a2e;
            --dark: #0f0f1a;
            --darker: #0a0a12;
            --accent: #e94560;
            --accent2: #533483;
            --text: #ffffff;
            --text-muted: #8892b0;
            --card-bg: #16213e;
            --card-hover: #1a2747;
            --border: rgba(245, 166, 35, 0.2);
            --gradient1: linear-gradient(135deg, #F5A623 0%, #e94560 100%);
            --gradient2: linear-gradient(135deg, #0f0f1a 0%, #1a1a2e 100%);
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: var(--dark);
            color: var(--text);
            line-height: 1.6;
            overflow-x: hidden;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        img {
            max-width: 100%;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        /* ==================== SCROLLBAR ==================== */
        ::-webkit-scrollbar {
            width: 8px;
        }
        ::-webkit-scrollbar-track {
            background: var(--darker);
        }
        ::-webkit-scrollbar-thumb {
            background: var(--primary);
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: var(--primary-dark);
        }

        /* ==================== PRELOADER ==================== */
        #preloader {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: var(--darker);
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 99999;
            transition: opacity 0.5s ease, visibility 0.5s ease;
        }

        #preloader.hidden {
            opacity: 0;
            visibility: hidden;
        }

        .loader {
            width: 60px;
            height: 60px;
            border: 4px solid rgba(245, 166, 35, 0.2);
            border-top: 4px solid var(--primary);
            border-radius: 50%;
            animation: spin 0.8s linear infinite;
        }

        @keyframes spin {
            to { transform: rotate(360deg); }
        }

        /* ==================== PARTICLES BG ==================== */
        #particles-container {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 0;
            pointer-events: none;
        }

        .particle {
            position: absolute;
            width: 2px;
            height: 2px;
            background: var(--primary);
            border-radius: 50%;
            opacity: 0;
            animation: float-particle 6s infinite;
        }

        @keyframes float-particle {
            0% { opacity: 0; transform: translateY(0) scale(1); }
            10% { opacity: 0.6; }
            90% { opacity: 0.1; }
            100% { opacity: 0; transform: translateY(-800px) scale(0); }
        }

        /* ==================== HEADER / NAVBAR ==================== */
        header {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 1000;
            transition: all 0.3s ease;
            background: transparent;
        }

        header.scrolled {
            background: rgba(10, 10, 18, 0.95);
            backdrop-filter: blur(20px);
            box-shadow: 0 2px 30px rgba(0, 0, 0, 0.5);
        }

        nav {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 15px 0;
        }

        .logo {
            font-size: 28px;
            font-weight: 800;
            letter-spacing: 2px;
            position: relative;
        }

        .logo span:first-child {
            color: var(--primary);
        }

        .logo span:last-child {
            color: var(--text);
        }

        .logo::after {
            content: '';
            position: absolute;
            bottom: -4px;
            left: 0;
            width: 100%;
            height: 2px;
            background: var(--gradient1);
            transform: scaleX(0);
            transition: transform 0.3s ease;
        }

        .logo:hover::after {
            transform: scaleX(1);
        }

        .nav-links {
            display: flex;
            gap: 35px;
            align-items: center;
        }

        .nav-links a {
            font-size: 14px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            position: relative;
            padding: 5px 0;
            transition: color 0.3s ease;
        }

        .nav-links a::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 50%;
            width: 0;
            height: 2px;
            background: var(--primary);
            transition: all 0.3s ease;
            transform: translateX(-50%);
        }

        .nav-links a:hover {
            color: var(--primary);
        }

        .nav-links a:hover::after {
            width: 100%;
        }

        .nav-cta {
            background: var(--gradient1);
            padding: 10px 25px !important;
            border-radius: 25px;
            font-weight: 700 !important;
            transition: transform 0.3s ease, box-shadow 0.3s ease !important;
        }

        .nav-cta::after {
            display: none !important;
        }

        .nav-cta:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 20px rgba(245, 166, 35, 0.4);
            color: white !important;
        }

        /* Mobile Menu Toggle */
        .menu-toggle {
            display: none;
            flex-direction: column;
            cursor: pointer;
            gap: 5px;
            z-index: 1001;
        }

        .menu-toggle span {
            width: 28px;
            height: 3px;
            background: var(--text);
            border-radius: 3px;
            transition: all 0.3s ease;
        }

        .menu-toggle.active span:nth-child(1) {
            transform: rotate(45deg) translate(5px, 5px);
        }

        .menu-toggle.active span:nth-child(2) {
            opacity: 0;
        }

        .menu-toggle.active span:nth-child(3) {
            transform: rotate(-45deg) translate(7px, -6px);
        }

        /* ==================== HERO SECTION ==================== */
        .hero {
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            overflow: hidden;
            background: radial-gradient(ellipse at center, rgba(26, 26, 46, 0.8) 0%, var(--dark) 70%);
        }

        .hero-bg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 900"><rect fill="%230f0f1a" width="1440" height="900"/><g fill="none" stroke="%23F5A623" stroke-width="0.3" opacity="0.1"><line x1="0" y1="0" x2="1440" y2="900"/><line x1="200" y1="0" x2="1440" y2="700"/><line x1="400" y1="0" x2="1440" y2="500"/><line x1="0" y1="200" x2="1200" y2="900"/><line x1="0" y1="400" x2="1000" y2="900"/><line x1="1440" y1="0" x2="0" y2="900"/><line x1="1240" y1="0" x2="0" y2="700"/></g></svg>') center/cover no-repeat;
            opacity: 0.5;
        }

        .hero-content {
            text-align: center;
            position: relative;
            z-index: 2;
            max-width: 900px;
            padding: 0 20px;
        }

        .hero-badge {
            display: inline-block;
            padding: 8px 20px;
            background: rgba(245, 166, 35, 0.1);
            border: 1px solid var(--border);
            border-radius: 30px;
            font-size: 13px;
            font-weight: 600;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: var(--primary);
            margin-bottom: 25px;
            animation: fadeInUp 0.8s ease;
        }

        .hero h1 {
            font-size: 72px;
            font-weight: 900;
            line-height: 1.1;
            margin-bottom: 25px;
            text-transform: uppercase;
            animation: fadeInUp 0.8s ease 0.2s both;
        }

        .hero h1 .highlight {
            background: var(--gradient1);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .hero p {
            font-size: 20px;
            color: var(--text-muted);
            max-width: 650px;
            margin: 0 auto 40px;
            line-height: 1.8;
            animation: fadeInUp 0.8s ease 0.4s both;
        }

        .hero-buttons {
            display: flex;
            gap: 20px;
            justify-content: center;
            flex-wrap: wrap;
            animation: fadeInUp 0.8s ease 0.6s both;
        }

        .btn {
            padding: 15px 40px;
            border-radius: 50px;
            font-size: 15px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            cursor: pointer;
            border: none;
            transition: all 0.3s ease;
            display: inline-flex;
            align-items: center;
            gap: 10px;
        }

        .btn-primary {
            background: var(--gradient1);
            color: white;
            box-shadow: 0 5px 25px rgba(245, 166, 35, 0.3);
        }

        .btn-primary:hover {
            transform: translateY(-3px);
            box-shadow: 0 8px 35px rgba(245, 166, 35, 0.5);
        }

        .btn-secondary {
            background: transparent;
            color: var(--text);
            border: 2px solid rgba(255, 255, 255, 0.2);
        }

        .btn-secondary:hover {
            border-color: var(--primary);
            color: var(--primary);
            transform: translateY(-3px);
        }

        .hero-stats {
            display: flex;
            justify-content: center;
            gap: 60px;
            margin-top: 60px;
            animation: fadeInUp 0.8s ease 0.8s both;
        }

        .hero-stat {
            text-align: center;
        }

        .hero-stat .number {
            font-size: 36px;
            font-weight: 800;
            color: var(--primary);
        }

        .hero-stat .label {
            font-size: 13px;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-top: 5px;
        }

        .scroll-indicator {
            position: absolute;
            bottom: 30px;
            left: 50%;
            transform: translateX(-50%);
            animation: bounce 2s infinite;
            z-index: 2;
        }

        .scroll-indicator .mouse {
            width: 26px;
            height: 40px;
            border: 2px solid var(--text-muted);
            border-radius: 13px;
            position: relative;
        }

        .scroll-indicator .mouse::before {
            content: '';
            position: absolute;
            top: 8px;
            left: 50%;
            transform: translateX(-50%);
            width: 4px;
            height: 8px;
            background: var(--primary);
            border-radius: 2px;
            animation: scroll-wheel 2s infinite;
        }

        @keyframes scroll-wheel {
            0% { opacity: 1; transform: translateX(-50%) translateY(0); }
            100% { opacity: 0; transform: translateX(-50%) translateY(12px); }
        }

        @keyframes bounce {
            0%, 20%, 50%, 80%, 100% { transform: translateX(-50%) translateY(0); }
            40% { transform: translateX(-50%) translateY(-10px); }
            60% { transform: translateX(-50%) translateY(-5px); }
        }

        @keyframes fadeInUp {
            from { opacity: 0; transform: translateY(30px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* ==================== SECTION STYLES ==================== */
        section {
            padding: 100px 0;
            position: relative;
            z-index: 1;
        }

        .section-header {
            text-align: center;
            margin-bottom: 60px;
        }

        .section-header .subtitle {
            font-size: 13px;
            text-transform: uppercase;
            letter-spacing: 3px;
            color: var(--primary);
            font-weight: 600;
            margin-bottom: 10px;
        }

        .section-header h2 {
            font-size: 42px;
            font-weight: 800;
            text-transform: uppercase;
            margin-bottom: 15px;
        }

        .section-header p {
            font-size: 16px;
            color: var(--text-muted);
            max-width: 600px;
            margin: 0 auto;
        }

        .section-divider {
            width: 60px;
            height: 4px;
            background: var(--gradient1);
            margin: 15px auto;
            border-radius: 2px;
        }

        /* ==================== NEWS SECTION ==================== */
        #news {
            background: var(--secondary);
        }

        .news-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
            gap: 30px;
        }

        .news-card {
            background: var(--card-bg);
            border-radius: 15px;
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, 0.05);
            transition: all 0.4s ease;
            cursor: pointer;
        }

        .news-card:hover {
            transform: translateY(-10px);
            border-color: var(--border);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
        }

        .news-image {
            width: 100%;
            height: 220px;
            background: linear-gradient(135deg, var(--accent2), var(--accent));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 50px;
            position: relative;
            overflow: hidden;
        }

        .news-card:nth-child(1) .news-image {
            background: linear-gradient(135deg, #1a1a2e, #533483);
        }

        .news-card:nth-child(2) .news-image {
            background: linear-gradient(135deg, #0f3460, #16213e);
        }

        .news-card:nth-child(3) .news-image {
            background: linear-gradient(135deg, #e94560, #533483);
        }

        .news-image::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
            transition: 0.6s;
        }

        .news-card:hover .news-image::before {
            left: 100%;
        }

        .news-tag {
            position: absolute;
            top: 15px;
            left: 15px;
            padding: 5px 15px;
            background: var(--primary);
            color: var(--dark);
            font-size: 11px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
            border-radius: 20px;
        }

        .news-body {
            padding: 25px;
        }

        .news-date {
            font-size: 12px;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 10px;
        }

